import os
import re
import numpy as np


def parse_output_flexible(filepath):
    result = {
        "has_content": False,
        "numeric_rows": [],
        "has_composition": False,
        "has_temperature": False,
        "has_enthalpy": False,
        "has_entropy": False,
        "has_free_energy": False,
        "line_count": 0,
        "header_info": {},
    }

    with open(filepath, "r") as <local-path>        content = f.read()
        lines = content.splitlines()

    result["line_count"] = len(lines)
    result["has_content"] = len(content.strip()) > 0

    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        parts = stripped.split()
        try:
            nums = [float(p) for p in parts]
            if len(nums) >= 2:
                result["numeric_rows"].append(nums)
        except ValueError:
            pass

    content_lower = content.lower()
    result["has_composition"] = any(kw in content_lower for kw in ["composition", "x =", "x=", "mole fraction", "\tx\t"])
    result["has_temperature"] = any(kw in content_lower for kw in ["temperature", "temp", " t=", " t =", "kelvin", "\tt\t"])
    result["has_enthalpy"] = any(kw in content_lower for kw in ["enthalpy", "h_mix", "delta_h", "mixing enthalpy", "h_gqca", "gqca_h"])
    result["has_entropy"] = any(kw in content_lower for kw in ["entropy", "s_mix", "delta_s", "s_gqca", "gqca_s"])
    result["has_free_energy"] = any(kw in content_lower for kw in ["free energy", "gibbs", "f_mix", "g_mix", "delta_g", "delta_f", "gqca_g"])

    return result


def parse_gold_output(filepath):
    result = {
        "J": None,
        "N": None,
        "configs": [],
        "data_rows": [],
        "specific_examples": [],
    }

    with open(filepath, "r") as <local-path>        lines = f.readlines()

    i = 0
    while i < len(lines):
        line = lines[i].strip()

        m = re.match(r"#\s*Total configurations \(J\):\s*(\d+)", line)
        if <local-path>            result["J"] = int(m.group(1))
        m = re.match(r"#\s*Sublattice atoms \(N\):\s*(\d+)", line)
        if <local-path>            result["N"] = int(m.group(1))

        m = re.match(
            r"#\s*Config\s+(\d+):\s*nj=(\d+),\s*gj=(\d+),\s*ej=([-\d.eE+]+),\s*dej=([-\d.eE+]+)",
            line,
        )
        if <local-path>            result["configs"].append({
                "idx": int(m.group(1)),
                "nj": int(m.group(2)),
                "gj": int(m.group(3)),
                "ej": float(m.group(4)),
                "dej": float(m.group(5)),
            })

        if not line.startswith("#") and line:
            parts = line.split()
            if len(parts) == 7:
                try:
                    result["data_rows"].append({
                        "x": float(parts[0]),
                        "T": float(parts[1]),
                        "h_gqca": float(parts[2]),
                        "h_random": float(parts[3]),
                        "s_gqca": float(parts[4]),
                        "s_ideal": float(parts[5]),
                        "f_mix": float(parts[6]),
                    })
                except ValueError:
                    pass

        m = re.match(r"#\s*x=([\d.]+),\s*T=(\d+)K:", line)
        if <local-path>            example = {
                "x": float(m.group(1)),
                "T": float(m.group(2)),
                "root": None,
                "probs_gqca": [],
                "probs_random": [],
            }
            i += 1
            if i < len(lines):
                rm = re.match(r"#\s*Root \(eta\):\s*([\d.eE+\-]+)", lines[i].strip())
                if rm:
                    example["root"] = float(rm.group(1))
                i += 1
            while i < len(lines):
                pm = re.match(
                    r"#\s*Config\s+\d+\s+probabilities\s*-\s*GQCA:\s*([\d.eE+\-]+),\s*Random:\s*([\d.eE+\-]+)",
                    lines[i].strip(),
                )
                if pm:
                    example["probs_gqca"].append(float(pm.group(1)))
                    example["probs_random"].append(float(pm.group(2)))
                    i += 1
                else:
                    break
            result["specific_examples"].append(example)
            continue

        i += 1

    return result


def extract_numeric_data(filepath):
    """Extract numeric rows, filtering out header lines."""
    rows = []
    with open(filepath, "r") as <local-path>        for line in <local-path>            stripped = line.strip()
            if not stripped or stripped.startswith("#"):
                continue
            parts = stripped.split()
            try:
                nums = [float(p) for p in parts]
                if len(nums) >= 2:
                    rows.append(nums)
            except ValueError:
                continue
    return rows


def check_physical_constraints_flexible(rows):
    """
    Check basic physical constraints, allowing NaN/Inf at boundary compositions (x=0, x=1).
    Returns (issues, interior_issues) where interior_issues are for x in (0,1).
    """
    all_issues = []
    interior_issues = []

    for i, row in enumerate(rows):
        if len(row) < 2:
            continue

        # Try to identify if this is a boundary composition row
        # First column is often x (composition), second is T
        is_boundary = False
        if len(row) >= 2:
            x_val = row[0]
            if abs(x_val) < 1e-10 or abs(x_val - 1.0) < 1e-10:
                is_boundary = True

        for j, val in enumerate(row):
            if np.isnan(val) or np.isinf(val):
                issue = f"Row {i}: NaN/Inf in column {j}"
                all_issues.append(issue)
                if not is_boundary:
                    interior_issues.append(issue)

    return all_issues, interior_issues


def try_match_gold_values(pred_rows, gold_data_rows, tolerance=0.05):
    """
    Try to match predicted values against gold values with flexible column matching.
    Returns match statistics.
    """
    if not gold_data_rows or not pred_rows:
        return None

    # Build lookup of gold values by (x, T)
    gold_lookup = {}
    for dr in gold_data_rows:
        key = (round(dr["x"], 4), round(dr["T"], 1))
        gold_lookup[key] = dr

    # Try to identify x and T columns in pred_rows
    # Assumption: first two numeric columns are x and T
    matches_found = 0
    total_checked = 0
    value_errors = []

    for row in pred_rows:
        if len(row) < 3:
            continue

        # Try x in first col, T in second col
        x_pred = row[0]
        T_pred = row[1]

        # Find matching gold row
        best_key = None
        best_dist = float('inf')
        for key in gold_lookup:
            dist = abs(key[0] - x_pred) + abs(key[1] - T_pred) / 1000.0
            if dist < best_dist:
                best_dist = dist
                best_key = key

        if best_key is None or best_dist > 0.1:
            continue

        gold_dr = gold_lookup[best_key]
        gold_vals = [gold_dr["h_gqca"], gold_dr["h_random"], gold_dr["s_gqca"],
                     gold_dr["s_ideal"], gold_dr["f_mix"]]

        # Try to match remaining columns against gold thermodynamic values
        pred_remaining = row[2:]
        for gold_val in gold_vals:
            if abs(gold_val) < 1e-10:
                continue
            for pred_val in pred_remaining:
                if np.isnan(pred_val) or np.isinf(pred_val):
                    continue
                rel_err = abs(pred_val - gold_val) / abs(gold_val)
                if rel_err < tolerance:
                    matches_found += 1
                    break
            total_checked += 1

    if total_checked == 0:
        return None

    return matches_found / total_checked


def eval():
    pred_path = "pred_results/pred_gqca2.txt"
    gold_path = "./gold_results/pred_gqca2.txt"

    # Step 1: Check file existence
    if not os.path.exists(pred_path):
        return (False, "Predicted output file pred_results/pred_gqca2.txt not found")

    # Step 2: Check file is not empty
    if os.path.getsize(pred_path) == 0:
        return (False, "Predicted output file is empty")

    # Step 3: Parse predicted output flexibly
    try:
        pred_flexible = parse_output_flexible(pred_path)
    except Exception as <local-path>        return (False, f"Failed to parse predicted output: {e}")

    if not pred_flexible["has_content"]:
        return (False, "Predicted output file has no content")

    # Step 4: Check that the file has numeric data
    pred_rows = extract_numeric_data(pred_path)
    if len(pred_rows) == 0:
        return (False, "No numeric data found in predicted output")

    # Step 5: Check for minimum required content
    if len(pred_rows) < 5:
        return (False, f"Too few data rows: found {len(pred_rows)}, expected at least 5")

    # Step 6: Check physical constraints - allow NaN/Inf at boundaries (x=0, x=1)
    all_issues, interior_issues = check_physical_constraints_flexible(pred_rows)

    # Count interior rows (non-boundary)
    interior_rows = [r for r in pred_rows if len(r) >= 1 and
                     abs(r[0]) > 1e-10 and abs(r[0] - 1.0) > 1e-10]

    # Fail only if too many interior rows have NaN/Inf
    if len(interior_rows) > 0:
        interior_nan_rate = len(interior_issues) / (len(interior_rows) * max(1, len(pred_rows[0])))
        if interior_nan_rate > 0.5:
            return (False, f"Too many NaN/Inf values in interior compositions: "
                    f"{len(interior_issues)} issues in {len(interior_rows)} interior rows. "
                    f"Sample: {interior_issues[:3]}")

    # Step 7: If gold file exists, do comparison
    gold_exists = os.path.exists(gold_path)

    if gold_exists:
        try:
            gold = parse_gold_output(gold_path)
        except Exception as <local-path>            gold = None

        if gold is not None and len(gold["data_rows"]) > 0:
            gold_rows = []
            for dr in gold["data_rows"]:
                gold_rows.append([dr["x"], dr["T"], dr["h_gqca"], dr["h_random"],
                                   dr["s_gqca"], dr["s_ideal"], dr["f_mix"]])

            pred_numeric_count = len(pred_rows)
            gold_numeric_count = len(gold_rows)

            # Check if predicted has sufficient number of rows
            if pred_numeric_count < gold_numeric_count * 0.3:
                return (False, f"Too few data rows: pred={pred_numeric_count}, gold={gold_numeric_count}")

            pred_ncols = len(pred_rows[0]) if pred_rows else 0
            gold_ncols = 7  # x, T, h_gqca, h_random, s_gqca, s_ideal, f_mix

            # Case 1: Same format - direct numerical comparison
            if pred_ncols == gold_ncols and len(pred_rows) == len(gold_rows):
                total_values = 0
                passing_values = 0
                errors = []
                max_rel_error = 0.0

                for pr, gr in zip(pred_rows, gold_rows):
                    for j, (pv, gv) in enumerate(zip(pr, gr)):
                        if np.isnan(pv) or np.isinf(pv):
                            # Check if boundary composition - allow NaN/Inf there
                            x_val = pr[0] if len(pr) > 0 else -1
                            if abs(x_val) < 1e-10 or abs(x_val - 1.0) < 1e-10:
                                continue  # Skip boundary NaN/Inf
                            total_values += 1
                            continue
                        total_values += 1
                        if abs(gv) > 1e-10:
                            rel_err = abs(pv - gv) / abs(gv)
                        else:
                            rel_err = abs(pv - gv)

                        max_rel_error = max(max_rel_error, rel_err)
                        if rel_err < 0.01:  # 1% tolerance
                            passing_values += 1
                        else:
                            errors.append(f"Row col {j}: pred={pv:.6f}, gold={gv:.6f}, rel_err={rel_err:.2e}")

                pass_rate = passing_values / total_values if total_values > 0 else 0

                if pass_rate >= 0.90:
                    return (True, f"PASS: {pass_rate*100:.1f}% of values match gold within 1% tolerance. "
                            f"Max rel error: {max_rel_error:.2e}")
                elif pass_rate >= 0.50:
                    return (False, f"Numerical accuracy too low: {pass_rate*100:.1f}% match. "
                            f"Max rel error: {max_rel_error:.2e}. Sample errors: {'; '.join(errors[:3])}")
                else:
                    return (False, f"Results don't match gold standard: only {pass_rate*100:.1f}% match. "
                            f"Sample errors: {'; '.join(errors[:3])}")

            # Case 2: Different column count - flexible matching
            else:
                # Try to find gold values in predicted data
                gold_h_values = set()
                gold_s_values = set()
                gold_f_values = set()

                for dr in gold["data_rows"]:
                    # Only use interior compositions for comparison
                    if abs(dr["x"]) > 1e-10 and abs(dr["x"] - 1.0) > 1e-10:
                        gold_h_values.add(round(dr["h_gqca"], 4))
                        gold_s_values.add(round(dr["s_gqca"], 4))
                        gold_f_values.add(round(dr["f_mix"], 4))

                pred_all_values = set()
                for row in pred_rows:
                    for val in row:
                        if not np.isnan(val) and not np.isinf(val):
                            pred_all_values.add(round(val, 4))

                h_overlap = len(gold_h_values & pred_all_values) / len(gold_h_values) if gold_h_values else 0
                s_overlap = len(gold_s_values & pred_all_values) / len(gold_s_values) if gold_s_values else 0
                f_overlap = len(gold_f_values & pred_all_values) / len(gold_f_values) if gold_f_values else 0

                max_overlap = max(h_overlap, s_overlap, f_overlap)

                if max_overlap > 0.5:
                    return (True, f"Output contains correct thermodynamic values "
                            f"(h_overlap={h_overlap:.1%}, s_overlap={s_overlap:.1%}, f_overlap={f_overlap:.1%})")

                # Try flexible value matching with tolerance
                match_rate = try_match_gold_values(pred_rows, gold["data_rows"], tolerance=0.05)

                if match_rate is not None and match_rate > 0.5:
                    return (True, f"Output values match gold with flexible column matching "
                            f"(match_rate={match_rate:.1%})")

                # Check if the solution has at least the right structure
                # (correct x, T values and some thermodynamic data)
                has_correct_structure = (
                    pred_numeric_count >= gold_numeric_count * 0.5 and
                    len(interior_issues) < len(interior_rows) * 0.3
                )

                if has_correct_structure and max_overlap > 0.1:
                    return (False, f"Partial match - structure correct but values don't match gold. "
                            f"h_overlap={h_overlap:.1%}, s_overlap={s_overlap:.1%}, f_overlap={f_overlap:.1%}. "
                            f"The solution may use incorrect thermodynamic formulas.")
                else:
                    return (False, f"Predicted values don't match gold standard. "
                            f"pred_cols={pred_ncols}, gold_cols={gold_ncols}, "
                            f"h_overlap={h_overlap:.1%}, s_overlap={s_overlap:.1%}. "
                            f"The solution uses incorrect thermodynamic formulas.")

    # Step 8: Basic sanity checks without gold comparison
    all_vals = []
    for row in pred_rows:
        all_vals.extend(row)

    valid_vals = [v for v in all_vals if not np.isnan(v) and not np.isinf(v)]

    if len(valid_vals) == 0:
        return (False, "No valid numeric values in output")

    unique_vals = len(set(f"{v:.4f}" for v in valid_vals))
    if unique_vals < 3:
        return (False, f"Output has too few distinct values: {unique_vals}")

    # Check that we have interior rows with valid data
    interior_valid_rows = 0
    for row in pred_rows:
        if len(row) >= 3:
            x_val = row[0]
            if abs(x_val) > 1e-10 and abs(x_val - 1.0) > 1e-10:
                row_valid = [v for v in row if not np.isnan(v) and not np.isinf(v)]
                if len(row_valid) >= 3:
                    interior_valid_rows += 1

    if interior_valid_rows < 3:
        return (False, f"Too few interior composition rows with valid data: {interior_valid_rows}")

    return (True, f"Output file exists with {len(pred_rows)} data rows and {len(valid_vals)} valid values. "
            f"Basic physical constraints satisfied.")


if __name__ == "__main__":
    result, reason = eval()
    print(f"Result: {'PASS' if result else 'FAIL'}")
    print(f"Reason: {reason}")

import os
import csv
import math
import numpy as np


def eval():
    pred_csv = "pred_results/pred_gqca2.csv"
    pred_config = "pred_results/pred_gqca2_config.txt"
    gold_csv = "./gold_results/pred_gqca2.csv"

    # Step 1: File existence
    for f, label in [(pred_csv, "pred CSV"), (pred_config, "pred config")]:
        if not os.path.isfile(f):
            return (False, f"Missing file: {label} ({f})")

    # Load CSV helper
    def load_csv(path):
        with open(path, "r") as fh:
            reader = csv.DictReader(fh)
            cols = reader.fieldnames
            rows = list(reader)
        return cols, rows

    try:
        pred_cols, pred_rows = load_csv(pred_csv)
    except Exception as <local-path>        return (False, f"Failed to parse pred CSV: {e}")

    # Step 2: Column compliance
    required_cols = ["composition", "temperature", "enthalpy_gqca", "enthalpy_random",
                     "entropy_gqca", "entropy_ideal", "free_energy"]
    for col in required_cols:
        if col not in pred_cols:
            return (False, f"Missing required column: {col}")

    # Step 3: Data completeness
    if len(pred_rows) == 0:
        return (False, "Predicted CSV has no data rows")

    # Check temperatures present
    try:
        pred_temps = sorted(set(float(r["temperature"]) for r in pred_rows))
    except (ValueError, KeyError) as <local-path>        return (False, f"Invalid temperature values: {e}")

    expected_temps = [300.0, 600.0, 900.0, 1200.0]
    for t in expected_temps:
        if not any(abs(pt - t) < 1.0 for pt in pred_temps):
            return (False, f"Missing temperature {t}K in predictions")

    # Check composition range
    try:
        pred_comps = sorted(set(float(r["composition"]) for r in pred_rows))
    except (ValueError, KeyError) as <local-path>        return (False, f"Invalid composition values: {e}")

    if pred_comps[0] > 0.05 or pred_comps[-1] < 0.95:
        return (False, f"Composition range too narrow: [{pred_comps[0]}, {pred_comps[-1]}]")

    if len(pred_comps) < 10:
        return (False, f"Too few distinct compositions: {len(pred_comps)}")

    # Step 4: Numerical validity - check for NaN/Inf only
    num_cols = ["enthalpy_gqca", "enthalpy_random", "entropy_gqca", "entropy_ideal", "free_energy"]
    for row_i, row in enumerate(pred_rows):
        for col in num_cols:
            try:
                val = float(row[col])
            except (ValueError, KeyError):
                return (False, f"Non-numeric value in row {row_i}, column {col}")
            if math.isnan(val) or math.isinf(val):
                return (False, f"NaN/Inf in row {row_i}, column {col}")

    # Step 5: Physical consistency checks

    # 5a: Free energy should generally decrease (become more negative) with temperature
    # for compositions away from endpoints (mixing region)
    decrease_count = 0
    total_checks = 0
    for comp in pred_comps:
        if comp < 0.05 or comp > 0.95:
            continue  # skip endpoints
        fe_by_temp = {}
        for row in pred_rows:
            if abs(float(row["composition"]) - comp) < 1e-6:
                fe_by_temp[float(row["temperature"])] = float(row["free_energy"])
        temps_sorted = sorted(fe_by_temp.keys())
        for i in range(len(temps_sorted) - 1):
            total_checks += 1
            if fe_by_temp[temps_sorted[i + 1]] <= fe_by_temp[temps_sorted[i]]:
                decrease_count += 1
    fe_decrease_ok = total_checks == 0 or (decrease_count / total_checks >= 0.6)

    # 5b: Ideal entropy should be symmetric (entropy at x should equal entropy at 1-x)
    entropy_symmetric_count = 0
    entropy_symmetric_total = 0
    comp_map = {}
    for row in pred_rows:
        x = round(float(row["composition"]), 4)
        t = round(float(row["temperature"]), 0)
        if (x, t) not in comp_map:
            comp_map[(x, t)] = float(row["entropy_ideal"])

    for (x, t), s in comp_map.items():
        mirror_x = round(1.0 - x, 4)
        if (mirror_x, t) in comp_map:
            entropy_symmetric_total += 1
            mirror_s = comp_map[(mirror_x, t)]
            # Use relative tolerance or absolute tolerance
            if abs(s) < 1e-15 and abs(mirror_s) < 1e-15:
                entropy_symmetric_count += 1
            elif abs(s) + abs(mirror_s) > 0:
                rel_diff = abs(s - mirror_s) / (abs(s) + abs(mirror_s)) * 2
                if rel_diff < 0.02:
                    entropy_symmetric_count += 1

    entropy_symmetric_ok = (entropy_symmetric_total == 0 or
                            entropy_symmetric_count / entropy_symmetric_total >= 0.7)

    # 5c: Ideal entropy should be maximized near x=0.5
    # Check that entropy at x=0.5 is higher than at x=0.1 and x=0.9
    entropy_shape_ok = True
    mid_comp = min(pred_comps, key=lambda c: abs(c - 0.5))
    low_comp = min(pred_comps, key=lambda c: abs(c - 0.1))
    high_comp = min(pred_comps, key=lambda c: abs(c - 0.9))

    mid_entropies = [float(r["entropy_ideal"]) for r in pred_rows 
                     if abs(float(r["composition"]) - mid_comp) < 1e-6]
    low_entropies = [float(r["entropy_ideal"]) for r in pred_rows 
                     if abs(float(r["composition"]) - low_comp) < 1e-6]
    high_entropies = [float(r["entropy_ideal"]) for r in pred_rows 
                      if abs(float(r["composition"]) - high_comp) < 1e-6]

    if mid_entropies and low_entropies and high_entropies:
        mid_s = np.mean(mid_entropies)
        low_s = np.mean(low_entropies)
        high_s = np.mean(high_entropies)
        if not (mid_s > low_s * 0.9 and mid_s > high_s * 0.9):
            entropy_shape_ok = False

    # 5d: Enthalpy should be zero (or near-zero) at endpoints x=0 and x=1
    # (mixing enthalpy is zero for pure components)
    endpoint_ok = True
    very_low = [r for r in pred_rows if float(r["composition"]) < 0.03]
    very_high = [r for r in pred_rows if float(r["composition"]) > 0.97]

    if very_low and very_high:
        # Get a typical scale for enthalpy
        all_enthalpies = [abs(float(r["enthalpy_random"])) for r in pred_rows]
        max_enthalpy = max(all_enthalpies) if all_enthalpies else 1.0

        low_h = np.mean([abs(float(r["enthalpy_random"])) for r in very_low])
        high_h = np.mean([abs(float(r["enthalpy_random"])) for r in very_high])

        # Endpoints should be much smaller than max
        if max_enthalpy > 1e-15:
            if low_h / max_enthalpy > 0.3 or high_h / max_enthalpy > 0.3:
                endpoint_ok = False

    physical_checks = {
        'fe_decrease': fe_decrease_ok,
        'entropy_symmetric': entropy_symmetric_ok,
        'entropy_shape': entropy_shape_ok,
        'endpoint_enthalpy': endpoint_ok,
    }
    physical_passes = sum(physical_checks.values())

    if physical_passes < 3:
        failed = [k for k, v in physical_checks.items() if not v]
        return (False, f"Physical consistency checks failed ({physical_passes}/4 passed). "
                       f"Failed: {failed}")

    # Step 6: Config file validation
    with open(pred_config, "r") as <local-path>        config_content = f.read()
    if len(config_content.strip()) < 10:
        return (False, "Config file is empty or too short")

    # Step 7: Compare against gold results if available (with flexible unit handling)
    gold_exists = os.path.isfile(gold_csv)

    if gold_exists:
        try:
            gold_cols, gold_rows = load_csv(gold_csv)
        except Exception as <local-path>            gold_rows = []

        if gold_rows:
            gold_lookup = {}
            for row in gold_rows:
                try:
                    key = (round(float(row["composition"]), 4), round(float(row["temperature"]), 0))
                    gold_lookup[key] = {col: float(row[col]) for col in num_cols if col in row}
                except (ValueError, KeyError):
                    continue

            # Build pred lookup
            pred_lookup = {}
            for row in pred_rows:
                try:
                    key = (round(float(row["composition"]), 4), round(float(row["temperature"]), 0))
                    pred_lookup[key] = {col: float(row[col]) for col in num_cols if col in row}
                except (ValueError, KeyError):
                    continue

            # Find matched keys
            common_keys = set(pred_lookup.keys()) & set(gold_lookup.keys())

            if len(common_keys) < 10:
                # Try fuzzy matching
                fuzzy_matched = 0
                for pk in pred_lookup:
                    for gk in gold_lookup:
                        if abs(pk[0] - gk[0]) < 0.02 and abs(pk[1] - gk[1]) < 1:
                            fuzzy_matched += 1
                            break
                if fuzzy_matched < 10:
                    return (False, f"Too few matched rows between pred and gold: {len(common_keys)}")

            if len(common_keys) >= 10:
                # For each column, compute a per-column scale factor to handle unit differences
                # Use median ratio approach per column

                col_scale_factors = {}
                for col in num_cols:
                    ratios = []
                    for key in common_keys:
                        p_val = pred_lookup[key].get(col, None)
                        g_val = gold_lookup[key].get(col, None)
                        if p_val is not None and g_val is not None:
                            if abs(g_val) > 1e-12 and abs(p_val) > 1e-12:
                                ratios.append(p_val / g_val)

                    if len(ratios) > 5:
                        ratios_sorted = sorted(ratios)
                        median_ratio = ratios_sorted[len(ratios_sorted) // 2]
                        # Check consistency
                        consistent = sum(1 for r in ratios 
                                        if abs(r / median_ratio - 1) < 0.3)
                        if consistent / len(ratios) > 0.6:
                            col_scale_factors[col] = median_ratio
                        else:
                            col_scale_factors[col] = 1.0
                    else:
                        col_scale_factors[col] = 1.0

                # Now compare with per-column scale factors
                mismatches = {col: 0 for col in num_cols}
                comparisons = {col: 0 for col in num_cols}

                for key in common_keys:
                    for col in num_cols:
                        p_val = pred_lookup[key].get(col, None)
                        g_val = gold_lookup[key].get(col, None)
                        if p_val is None or g_val is None:
                            continue

                        scale = col_scale_factors.get(col, 1.0)
                        p_scaled = p_val / scale if abs(scale) > 1e-15 else p_val

                        comparisons[col] += 1
                        if abs(g_val) < 1e-10:
                            if abs(p_scaled) > 1e-6:
                                mismatches[col] += 1
                        else:
                            rel_err = abs(p_scaled - g_val) / abs(g_val)
                            if rel_err > 0.15:  # 15% tolerance per column
                                mismatches[col] += 1

                # Check per-column error rates
                col_errors = {}
                for col in num_cols:
                    if comparisons[col] > 0:
                        col_errors[col] = mismatches[col] / comparisons[col]
                    else:
                        col_errors[col] = 0.0

                # Allow some columns to have higher error (e.g., GQCA-specific ones)
                # Core columns that must match: enthalpy_random, entropy_ideal
                core_cols = ["enthalpy_random", "entropy_ideal"]
                gqca_cols = ["enthalpy_gqca", "entropy_gqca", "free_energy"]

                core_failures = [col for col in core_cols if col_errors.get(col, 0) > 0.25]
                gqca_failures = [col for col in gqca_cols if col_errors.get(col, 0) > 0.35]

                if len(core_failures) > 0:
                    return (False, f"Core columns have too many mismatches: {core_failures}. "
                                   f"Error rates: {col_errors}")

                if len(gqca_failures) > len(gqca_cols) * 0.6:
                    return (False, f"GQCA columns have too many mismatches: {gqca_failures}. "
                                   f"Error rates: {col_errors}")

                # Additional check: correlation between pred and gold for key columns
                for col in ["enthalpy_random", "entropy_ideal"]:
                    pred_vals = []
                    gold_vals = []
                    scale = col_scale_factors.get(col, 1.0)
                    for key in common_keys:
                        p_val = pred_lookup[key].get(col, None)
                        g_val = gold_lookup[key].get(col, None)
                        if p_val is not None and g_val is not None:
                            pred_vals.append(p_val / scale if abs(scale) > 1e-15 else p_val)
                            gold_vals.append(g_val)

                    if len(pred_vals) > 10:
                        pred_arr = np.array(pred_vals)
                        gold_arr = np.array(gold_vals)
                        # Check correlation
                        if np.std(pred_arr) > 1e-15 and np.std(gold_arr) > 1e-15:
                            corr = np.corrcoef(pred_arr, gold_arr)[0, 1]
                            if corr < 0.8:
                                return (False, f"Low correlation for {col}: {corr:.3f}")

    return (True, f"All checks passed. {len(pred_rows)} rows found. "
                  f"Physical consistency: {physical_passes}/4. "
                  f"Compositions: {len(pred_comps)}, Temperatures: {len(pred_temps)}")


